{
  "name": "opencode-dollar-skills",
  "version": "0.2.0",
  "description": "OpenCode V2 $skill autocomplete through an isolated internal composer bridge, plus deterministic prompt admission.",
  "type": "module",
  "license": "MIT",
  "author": "Marlon Passos",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "skills",
    "autocomplete",
    "tui"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/MarlonPassos-git/opencode-dollar-skills.git"
  },
  "homepage": "https://github.com/MarlonPassos-git/opencode-dollar-skills#readme",
  "bugs": {
    "url": "https://github.com/MarlonPassos-git/opencode-dollar-skills/issues"
  },
  "engines": {
    "node": ">=22"
  },
  "packageManager": "pnpm@11.9.0",
  "main": "./index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./index.js"
    },
    "./tui": {
      "types": "./tui.d.ts",
      "import": "./tui.js"
    }
  },
  "files": [
    "index.js",
    "dist",
    "tui.js",
    "tui.d.ts",
    "README.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "peerDependencies": {
    "@opentui/core": "*",
    "solid-js": "*"
  },
  "peerDependenciesMeta": {
    "@opentui/core": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "scripts": {
    "build": "node scripts/build.mjs",
    "check": "pnpm lint && pnpm type-check && pnpm build && pnpm test && pnpm knip",
    "coverage": "vitest run --coverage",
    "demo": "node scripts/demo.mjs",
    "doctor": "node scripts/doctor.mjs",
    "format": "biome format --write .",
    "knip": "knip --no-progress",
    "lint": "biome check .",
    "lint:fix": "biome check --write .",
    "package:zip": "node scripts/package.mjs",
    "preview": "node scripts/preview.mjs",
    "smoke:live": "node scripts/smoke-live.mjs",
    "smoke:mock": "node --import ./test/helpers/register-mock-runtime.mjs scripts/smoke-mock.mjs",
    "test": "vitest run",
    "test:integration": "vitest run test/integration",
    "test:unit": "vitest run test/unit",
    "type-check": "tsc -p tsconfig.json --noEmit"
  },
  "devDependencies": {
    "@biomejs/biome": "^2.5.14",
    "@m-p-toolkit/biome-config": "^2.0.0",
    "@vitest/coverage-v8": "^5.0.1",
    "knip": "^6.37.0",
    "typescript": "^7.0.2",
    "vite": "^8.3.0",
    "vitest": "^5.0.1"
  }
}
